Method.Source:
    /// <summary>
    /// The mapEntityToDatasource method
    /// </summary>
    /// <param name = "_entityCtx">The entity runtime context parameter</param>
    /// <param name = "_dataSourceCtx">The datasource runtime context parameter</param>
    public void mapEntityToDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
    {
        super(_entityCtx, _dataSourceCtx);

        if (_dataSourceCtx.name() == dataEntityDataSourceStr(METPlannerCodeAssignmentRulesEntity, METPlannerCodeAssignmentRules))
        {
            METPlannerCodeAssignmentRules dsPlannerAssignmentRules = _dataSourceCtx.getBuffer();
            EcoResCategoryHierarchy ecoResCategoryHierarchy = EcoResCategoryHierarchy::findByName(this.RuleProductCatHierarchy);
            EcoResCategory ecoResCategory = EcoResCategory::findByCode(this.RuleProductCat, ecoResCategoryHierarchy.RecId);
            
            dsPlannerAssignmentRules.RuleProductCategory = ecoResCategory.RecId;
            dsPlannerAssignmentRules.RuleProductCategoryHierarchy = ecoResCategoryHierarchy.RecId;
            
        }
    }

    /// <summary>
    /// The postload method
    /// </summary>
    public void postLoad()
    {
        EcoResCategory ecoResCategory;
        EcoResCategoryHierarchy ecoResCategoryHierarchy;

        super();

        ecoResCategory = EcoResCategory::find(this.RuleProductCategoryRecId);
        ecoResCategoryHierarchy = EcoResCategoryHierarchy::find(this.RuleProductCategoryHierarchyRecId);

        this.RuleProductCat = ecoResCategory.Code;
        this.RuleProductCatHierarchy = ecoResCategoryHierarchy.Name;
    }

    /// <summary>
    /// The validateWrite method of the entity
    /// </summary>
    /// <returns>True or false</returns>
    public boolean validateWrite()
    {
        boolean ret;
    
        ret = super();

        if (ret)
        {
            if (this.RuleAssignmentType == METRuleAssignmentType::Product)
            {
                this.RuleVendorAccount = METConstants::emptyString;
                this.RuleVendorSite = METConstants::emptyString;
            }
            else if (this.RuleAssignmentType == METRuleAssignmentType::Vendor)
            {
                this.RuleProductCategoryRecId = 0;
                this.RuleProductCategoryHierarchyRecId = 0;
                this.RuleProductCat = METConstants::emptyString;
                this.RuleProductCatHierarchy = METConstants::emptyString;
            }
        }

        if (ret)
        {
            if (this.RuleAssignmentType == METRuleAssignmentType::Product &&
                (this.RuleProductCat == METConstants::emptyString || this.RuleProductCatHierarchy == METConstants::emptyString))
            {
                ret = checkFailed("@MET:METPlannerCodePCPHError");
            }

            if (this.RuleAssignmentType == METRuleAssignmentType::Vendor && 
                (this.RuleVendorAccount == METConstants::emptyString || this.RuleVendorSite == METConstants::emptyString))
            {
                ret = checkFailed("@MET:METPlannerCodeVAVSError");
            }

            if (this.RuleAssignmentType == METRuleAssignmentType::VendorProduct &&
                (this.RuleProductCat == METConstants::emptyString || this.RuleProductCatHierarchy == METConstants::emptyString
                    || this.RuleVendorAccount == METConstants::emptyString || this.RuleVendorSite == METConstants::emptyString))
                 
            {
                ret = checkFailed("@MET:METPlannerCodeValError");
            }
        }
    
        return ret;
    }
